<script setup>import AppShell from'../../Layouts/AppShell.vue';import GroupNav from'../../Components/GroupNav.vue';import StateCard from'../../Components/StateCard.vue';import UiAlert from'../../Components/UiAlert.vue';import{Head,Link,useForm}from'@inertiajs/vue3';import{ref}from'vue';const p=defineProps({group:Object,canManage:Boolean,photos:Array,members:Array,invites:Array,indexRun:Object});const upload=useForm({photos:[]}),selection=ref([]),exportForm=useForm({photo_ids:[]});function choose(e){upload.clearErrors();upload.photos=[...e.target.files]}function makeExport(){exportForm.photo_ids=[...selection.value];exportForm.post(`/groups/${p.group.id}/exports`,{onSuccess:()=>selection.value=[]})}</script>
<template><AppShell><Head :title="group.name"/><GroupNav :group="group" :can-manage="canManage"/><section class="mt-5 overflow-hidden rounded-2xl bg-ink text-white"><div class="bg-gradient-to-r from-indigo/70 via-transparent to-coral/20 p-7 md:p-10"><p class="text-xs font-bold uppercase tracking-[.18em] text-white/55">Group workspace</p><h1 class="mt-3 font-display text-3xl font-bold md:text-4xl">{{group.name}}</h1><p class="mt-3 text-sm text-white/55">{{group.location||'Private project'}} · {{group.privacy}}</p></div></section><div class="mt-6 grid gap-6 xl:grid-cols-[1fr_320px]"><div><div v-if="canManage" class="panel p-5"><div class="flex flex-wrap items-center justify-between gap-3"><div><h2 class="font-display text-xl font-bold">Upload & processing</h2><p class="mt-1 text-sm text-black/45">Uploads are stored privately before durable processing begins.</p></div><label class="btn-primary cursor-pointer">Choose photos<input type="file" multiple accept="image/jpeg,image/png,image/webp" class="hidden" @change="choose"></label></div><UiAlert v-if="upload.errors.photos" class="mt-4" tone="error">{{upload.errors.photos}}</UiAlert><div v-if="upload.photos.length" class="mt-5 rounded-xl bg-indigo/5 p-4"><p class="font-semibold">{{upload.photos.length}} files ready</p><button class="btn-primary mt-3" :disabled="upload.processing" @click="upload.post(`/groups/${group.id}/photos`)">{{upload.processing?'Uploading…':'Upload and monitor processing'}}</button></div></div><div class="mt-8 flex flex-wrap items-end justify-between gap-3"><div><h2 class="font-display text-xl font-bold">Group Gallery</h2><p class="mt-1 text-sm text-black/45">Only currently authorized media is shown.</p></div><button v-if="canManage&&selection.length" class="btn-secondary" :disabled="exportForm.processing" @click="makeExport">Export {{selection.length}} selected</button></div><StateCard v-if="!photos.length" class="mt-4" title="No photographs yet" message="An authorized photographer can upload the first photographs."/><div v-else class="photo-grid mt-4 grid grid-cols-2 gap-1 md:grid-cols-3 xl:grid-cols-4"><div v-for="photo in photos" :key="photo.id" class="relative aspect-[4/3] overflow-hidden bg-black/10"><Link :href="`/groups/${group.id}/photos/${photo.id}`" class="block h-full w-full"><img :src="photo.url" :alt="photo.original_filename" class="h-full w-full object-cover"></Link><label v-if="canManage" class="absolute left-2 top-2 grid h-8 w-8 place-items-center bg-white/90 shadow"><input v-model="selection" :value="photo.id" type="checkbox" class="h-4 w-4 accent-indigo" :aria-label="`Select ${photo.original_filename}`"></label></div></div></div><aside v-if="canManage" class="space-y-5"><div class="panel p-5"><h3 class="font-display font-bold">Participants</h3><p class="mt-2 text-3xl font-bold">{{members.length}}</p><Link :href="`/groups/${group.id}/members`" class="btn-muted mt-4 w-full">Manage participants</Link></div><div class="panel p-5"><h3 class="font-display font-bold">Invitation access</h3><p class="mt-2 text-sm text-black/50">{{invites.length}} access levels configured</p><Link :href="`/groups/${group.id}/access-invites`" class="btn-secondary mt-4 w-full">Manage invitations</Link></div><div class="panel p-5"><h3 class="font-display font-bold">Face indexing</h3><p class="mt-2 text-sm text-black/50">{{indexRun?.state||'Not started'}}</p><Link :href="`/groups/${group.id}/operations`" class="btn-secondary mt-4 w-full">Processing & exports</Link></div></aside></div></AppShell></template>
